using System;
using System.Reflection;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;

public class CombatRailJourneyTests {
 [Test] public void HighRangeStartsAtExplicitCruise(){var config=Config();config["throttleMaximumBps"]=13000;config["throttleCruiseBps"]=10000;var j=Activator.CreateInstance(typeof(BasicCombatSimulation).Assembly.GetType("LastRail.Battle.CombatRailJourney"),new object[]{config});Assert.AreEqual(10000,(int)State(j)["throttleBps"]);Call(j,"SetThrottle",13000);Call(j,"AdvanceDistance",10000000L);Assert.AreEqual(13000,(long)State(j)["distanceMm"]);}
 [Test] public void RestoreRejectsFabricatedConfirmAndInvalidJournalOrder(){var j=New();Call(j,"ObserveCompletedWaves",3);Call(j,"Confirm","fork-3","left",5L);var good=State(j);foreach(var mode in new[]{"empty","negative","mismatch","no-open","phase"}){var bad=(JObject)good.DeepClone();if(mode=="empty")bad["journal"]=new JArray();if(mode=="negative")bad["confirmed"][0]["atTick"]=-1;if(mode=="mismatch")bad["journal"][1]["optionId"]="right";if(mode=="no-open")bad["journal"][0]["kind"]="PREVIEW";if(mode=="phase")bad["phase"]="Selecting";Assert.Throws<ArgumentException>(()=>Call(New(),"Restore",bad),mode);}}
 public static JObject Config()=>JObject.Parse(@"{'version':'rail-journey-v1','selectionScaleBps':100,'recoveryMs':600,'baseSpeedMillimetersPerSecond':10000,'throttleMinimumBps':7000,'throttleMaximumBps':10000,'offers':[{'id':'fork-3','afterCompletedWaves':3,'options':[{'id':'left','routeId':'left-track','label':'분대 화력','description':'분대 공격력 +5%','augmentId':'rail_aug_squad_5','effect':{'kind':'ADD_BPS','stat':'SQUAD_DAMAGE','valueBps':500}},{'id':'right','routeId':'right-track','label':'열차 화력','description':'열차 공격력 +5%','augmentId':'rail_aug_train_5','effect':{'kind':'ADD_BPS','stat':'TRAIN_DAMAGE','valueBps':500}}]}]}");
 static object New(){var t=typeof(BasicCombatSimulation).Assembly.GetType("LastRail.Battle.CombatRailJourney");Assert.NotNull(t,"Rail journey state engine missing");return Activator.CreateInstance(t,new object[]{Config()});}
 static object Call(object target,string name,params object[] args){try{return target.GetType().GetMethod(name).Invoke(target,args);}catch(TargetInvocationException e){throw e.InnerException;}}
 static JObject State(object target)=>(JObject)Call(target,"Capture");
 [Test] public void CannotSkipDueJunctionOrAdvanceWavesDuringSelection(){var a=new CombatRailJourney(Config());Assert.Throws<ArgumentException>(()=>a.CheckBoundary(4,1));a.CheckBoundary(3,1);Assert.Throws<ArgumentException>(()=>a.CheckBoundary(4,2));}
 [Test] public void PendingJunctionHoldsDistanceIndefinitelyAndCommitsExactlyOnce(){var j=New();Call(j,"AdvanceDistance",10000000L);Call(j,"ObserveCompletedWaves",3);var before=State(j);Assert.AreEqual("Selecting",(string)before["phase"]);Call(j,"Preview",1);Assert.AreEqual(0,((JArray)State(j)["confirmed"]).Count);for(int i=0;i<500;i++){Assert.AreEqual(100000L,Call(j,"TransformElapsed",10000000L,false));Call(j,"AdvanceDistance",10000000L);Call(j,"ObserveCompletedWaves",3);}Assert.AreEqual((long)before["distanceMm"],(long)State(j)["distanceMm"]);Assert.IsTrue((bool)Call(j,"Confirm","fork-3","right",123L));Assert.IsFalse((bool)Call(j,"Confirm","fork-3","right",123L));Assert.AreEqual(1,((JArray)State(j)["confirmed"]).Count);Assert.AreEqual("Recovering",(string)State(j)["phase"]);Assert.AreEqual("right-track",(string)State(j)["confirmed"][0]["routeId"]);}
 [Test] public void RecoveryIntegralIsPartitionInvariantAndPausePreservesProgress(){var a=New();var b=New();foreach(var j in new[]{a,b}){Call(j,"ObserveCompletedWaves",3);Call(j,"Confirm","fork-3","left",1L);}long all=(long)Call(a,"TransformElapsed",6000000L,false),parts=0;for(int i=0;i<60;i++)parts+=(long)Call(b,"TransformElapsed",100000L,false);Assert.That(parts,Is.EqualTo(all).Within(1));Assert.That(all,Is.EqualTo(3030000L).Within(1));Assert.AreEqual("Cruising",(string)State(a)["phase"]);var c=New();Call(c,"ObserveCompletedWaves",3);Call(c,"Confirm","fork-3","left",1L);Call(c,"TransformElapsed",1000000L,false);var state=State(c).ToString();Assert.AreEqual(0L,Call(c,"TransformElapsed",50000000L,true));Assert.AreEqual(state,State(c).ToString());}
 [Test] public void StateRoundTripKeepsFractionThrottleAndSelection(){var j=New();Call(j,"SetThrottle",8000);Call(j,"ObserveCompletedWaves",3);Call(j,"TransformElapsed",37L,false);Call(j,"Preview",1);var snapshot=State(j);var restored=New();Call(restored,"Restore",snapshot);Assert.IsTrue(JToken.DeepEquals(snapshot,State(restored)));Assert.AreEqual(Call(j,"TransformElapsed",63L,false),Call(restored,"TransformElapsed",63L,false));Assert.AreEqual(8000,(int)State(restored)["throttleBps"]);var bad=(JObject)snapshot.DeepClone();bad["offerIndex"]=999;Assert.Throws<ArgumentException>(()=>Call(restored,"Restore",bad));}
 [Test] public void TravelUsesActualThrottleAndRejectsInvalidConfiguration(){var a=New();var b=New();Call(a,"SetThrottle",7000);Call(b,"SetThrottle",10000);Call(a,"AdvanceDistance",10000000L);Call(b,"AdvanceDistance",10000000L);Assert.AreEqual(7000,(long)State(a)["distanceMm"]);Assert.AreEqual(10000,(long)State(b)["distanceMm"]);Assert.Throws<ArgumentOutOfRangeException>(()=>Call(a,"SetThrottle",0));Assert.Throws<ArgumentException>(()=>Call(a,"Confirm","unknown","right",1L));}
}
